import { writeFile } from 'node:fs/promises';
import { seedState } from '../data/seed-data.js';
import { migrateV1State } from '../js/migrate-v1.js';

const s = migrateV1State(seedState);
const q = (v) => v === null || v === undefined ? 'null' : `'${String(v).replaceAll("'", "''")}'`;
const n = (v) => v === null || v === undefined ? 'null' : String(v);
const b = (v) => v ? 'true' : 'false';
const j = (v) => `${q(JSON.stringify(v))}::jsonb`;
const lines = [
  '-- DormFlow v2 deterministic migration from bundled workbook/v1 seed',
  '-- Generated by: node scripts/generate-migration-sql.mjs',
  '-- Run AFTER supabase/schema.sql. Safe to re-run: IDs use ON CONFLICT.',
  'begin;',
  `insert into public.households(id,name,product_name,currency) values(${q(s.household.id)},${q(s.household.name)},${q(s.household.productName)},${q(s.household.currency)}) on conflict(id) do update set name=excluded.name,product_name=excluded.product_name,currency=excluded.currency;`,
];
for (const x of s.members) lines.push(`insert into public.members(id,household_id,name,short_name,color,active,sort_order,qr_image,default_split) values(${q(x.id)},${q(x.householdId)},${q(x.name)},${q(x.shortName)},${q(x.color)},${b(x.active)},${n(x.sortOrder)},${q(x.qrImage)},${b(x.defaultSplit)}) on conflict(id) do nothing;`);
for (const x of s.billingPeriods) lines.push(`insert into public.billing_periods(id,household_id,month,status,initialized_at,source) values(${q(x.id)},${q(x.householdId)},${q(x.month)},${q(x.status)},${q(x.initializedAt)},${q(x.source)}) on conflict(id) do nothing;`);
for (const x of s.expenseCategories) lines.push(`insert into public.expense_categories(id,household_id,name,sort_order) values(${q(x.id)},${q(x.householdId)},${q(x.name)},${n(x.sortOrder)}) on conflict(id) do nothing;`);
for (const x of s.paylaterAccounts) lines.push(`insert into public.paylater_accounts(id,household_id,provider,borrower_id,covered_by_id,original_total_cents,installment_count,notes,active,source) values(${q(x.id)},${q(x.householdId)},${q(x.provider)},${q(x.borrowerId)},${q(x.coveredById)},${n(x.originalTotalCents)},${n(x.installmentCount)},${q(x.notes)},${b(x.active)},${q(x.source)}) on conflict(id) do nothing;`);
for (const x of s.paylaterInstallments) lines.push(`insert into public.paylater_installments(id,account_id,period_month,due_date,amount_cents,each_per_person_cents,status,source_loan_id,sequence) values(${q(x.id)},${q(x.accountId)},${q(x.periodMonth)},${q(x.dueDate)},${n(x.amountCents)},${n(x.eachPerPersonCents)},${q(x.status)},${q(x.sourceLoanId)},${n(x.sequence)}) on conflict(id) do nothing;`);
for (const x of s.expenses) lines.push(`insert into public.expenses(id,household_id,period_id,category_id,description,amount_cents,source_amount_cents,expense_date,due_date,status,notes,source_kind,subcategory,external_creditor_label,paylater_installment_id,legacy_source_id) values(${q(x.id)},${q(x.householdId)},${q(x.periodId)},${q(x.categoryId)},${q(x.description)},${n(x.amountCents)},${n(x.sourceAmountCents)},${q(x.expenseDate)},${q(x.dueDate)},${q(x.status)},${q(x.notes)},${q(x.sourceKind)},${q(x.subcategory)},${q(x.externalCreditorLabel)},${q(x.paylaterInstallmentId)},${q(x.legacySourceId)}) on conflict(id) do nothing;`);
for (const x of s.expensePayers) lines.push(`insert into public.expense_payers(id,expense_id,member_id,amount_cents) values(${q(x.id)},${q(x.expenseId)},${q(x.memberId)},${n(x.amountCents)}) on conflict(id) do nothing;`);
for (const x of s.expenseSplits) lines.push(`insert into public.expense_splits(id,expense_id,member_id,amount_cents,percentage,source) values(${q(x.id)},${q(x.expenseId)},${q(x.memberId)},${n(x.amountCents)},${n(x.percentage)},${q(x.source)}) on conflict(id) do nothing;`);
for (const x of s.obligations) lines.push(`insert into public.obligations(id,expense_id,period_id,debtor_id,creditor_id,creditor_label,amount_cents,due_date,source_kind) values(${q(x.id)},${q(x.expenseId)},${q(x.periodId)},${q(x.debtorId)},${q(x.creditorId)},${q(x.creditorLabel)},${n(x.amountCents)},${q(x.dueDate)},${q(x.sourceKind)}) on conflict(id) do nothing;`);
for (const x of s.payments) lines.push(`insert into public.payments(id,household_id,payer_id,recipient_id,recipient_label,amount_cents,paid_at,method,reference_masked,notes,status,source) values(${q(x.id)},${q(x.householdId)},${q(x.payerId)},${q(x.recipientId)},${q(x.recipientLabel)},${n(x.amountCents)},${q(x.paidAt)},${q(x.method)},${q(x.referenceMasked)},${q(x.notes)},${q(x.status)},${q(x.source)}) on conflict(id) do nothing;`);
for (const x of s.paymentAllocations) lines.push(`insert into public.payment_allocations(id,payment_id,obligation_id,amount_cents,status,created_at) values(${q(x.id)},${q(x.paymentId)},${q(x.obligationId)},${n(x.amountCents)},${q(x.status)},${q(x.createdAt)}) on conflict(id) do nothing;`);
for (const x of s.paymentChannels) lines.push(`insert into public.payment_channels(id,household_id,member_id,type,label,account_name,masked_account,qr_image,visibility,active,notes) values(${q(x.id)},${q(x.householdId)},${q(x.memberId)},${q(x.type)},${q(x.label)},${q(x.accountName)},${q(x.maskedAccount)},${q(x.qrImage)},${q(x.visibility)},${b(x.active)},${q(x.notes)}) on conflict(id) do nothing;`);
for (const x of s.splitPresets) lines.push(`insert into public.split_presets(id,household_id,name,mode,member_ids,config,active) values(${q(x.id)},${q(x.householdId)},${q(x.name)},${q(x.mode)},${j(x.memberIds)},'{}'::jsonb,true) on conflict(id) do nothing;`);
lines.push(`insert into public.audit_log(id,household_id,actor,at,entity_type,entity_id,action,summary) values('audit-migration',${q(s.household.id)},'migration','2026-08-31T12:00:00+08:00','migration','v1','migrate','Migrated workbook-backed v1 seed to DormFlow v2 relational schema') on conflict(id) do nothing;`);
lines.push('commit;');
lines.push("select 'August obligations' as check_name, sum(es.amount_cents) as cents from public.expense_splits es join public.expenses e on e.id=es.expense_id where e.period_id='2026-08';");
lines.push("select 'August current outstanding' as check_name, sum(outstanding_cents) as cents from public.public_obligation_balances where period_id='2026-08';");
await writeFile(new URL('../supabase/migrate-v1.sql', import.meta.url), lines.join('\n')+'\n');
console.log(`Generated supabase/migrate-v1.sql (${lines.length} statements/lines)`);
